(478394, 46217, 10848, '<td valign="top">Beautiful shot, the sunrise is wonderful, and the church in silouette is great</td>', 'Beautiful shot, the sunrise is wonderful, and the church in silouette is great', '2003-11-10 00:09:29.000000', NULL, 1),
(478396, 45665, 772, '<td valign="top">very interesting exposure here.  I love the detail that is still visible in the darkness...</td>', 'very interesting exposure here.  I love the detail that is still visible in the darkness...', '2003-11-10 00:14:15.000000', NULL, 1),
(478398, 45874, 259, '<td valign="top">believe it or not i was joking with my friend about this very idea.  i love it.</td>', 'believe it or not i was joking with my friend about this very idea.  i love it.', '2003-11-10 00:17:39.000000', NULL, 1),
(478400, 46285, 6202, '<td valign="top">Love your thinking here.  Very good and very orginal, although could be considered very sinful as well.</td>', 'Love your thinking here.  Very good and very orginal, although could be considered very sinful as well.', '2003-11-10 00:18:31.000000', NULL, 1),
