(478421, 46249, 9441, '<td valign="top">very beautiful photo...nice soft lighting creates a fantastic mood here!</td>', 'very beautiful photo...nice soft lighting creates a fantastic mood here!', '2003-11-10 00:32:04.000000', NULL, 1),
(478423, 46202, 9441, '<td valign="top">fantastic capture of the lights!!  Great job.</td>', 'fantastic capture of the lights!!  Great job.', '2003-11-10 00:32:42.000000', NULL, 1),
