(478430, 45455, 13749, '<td valign="top">might benefit from a more level ground/horizon line</td>', 'might benefit from a more level ground/horizon line', '2003-11-10 00:35:54.000000', NULL, 1),
(478434, 46221, 13381, '<td valign="top">A beautiful shot.</td>', 'A beautiful shot.', '2003-11-10 00:38:43.000000', NULL, 1),
(478437, 46201, 12253, '<td valign="top">Nice scenery,  seems a bit unsharp though, especially the barn, which as I see it is the focal point.  Also, the foreground framing would work better without that one bare branch that goes through the middle of the photo.  Lasly, I''m not too sure why it''s sacred, it might have helped to say something in the title.</td>', 'Nice scenery,  seems a bit unsharp though, especially the barn, which as I see it is the focal point.  Also, the foreground framing would work better without that one bare branch that goes through the middle of the photo.  Lasly, I''m not too sure why it''s sacred, it might have helped to say something in the title.', '2003-11-10 00:41:21.000000', NULL, 1),
(478439, 45875, 13381, '<td valign="top">How lucky you must be to have a morning spot like this one.</td>', 'How lucky you must be to have a morning spot like this one.', '2003-11-10 00:42:58.000000', NULL, 1),
(478449, 46202, 13749, '<td valign="top">needs some more foreground shapes, or cropping - especially on the left</td>', 'needs some more foreground shapes, or cropping - especially on the left', '2003-11-10 00:56:53.000000', NULL, 1),
