(478524, 45700, 10848, '<td valign="top">this is quite an unusual cloud formation, it is beautiful, the colors are outstanding</td>', 'this is quite an unusual cloud formation, it is beautiful, the colors are outstanding', '2003-11-10 03:01:42.000000', NULL, 1),
(478525, 46329, 10170, '<td valign="top">A very moving shot indeed.  Nicely composed, good DOF.</td>', 'A very moving shot indeed.  Nicely composed, good DOF.', '2003-11-10 03:08:55.000000', NULL, 1),
(478526, 45918, 10170, '<td valign="top">The water droplet lines are a great effect here.  Nice shot.</td>', 'The water droplet lines are a great effect here.  Nice shot.', '2003-11-10 03:11:09.000000', NULL, 1),
(478527, 45268, 10170, '<td valign="top">A little over exposed for my taste on the window, but otherwise a lovely shot.</td>', 'A little over exposed for my taste on the window, but otherwise a lovely shot.', '2003-11-10 03:11:50.000000', NULL, 1),
(478528, 46237, 10170, '<td valign="top">Great choice of where to take this shot from.  Very effective.</td>', 'Great choice of where to take this shot from.  Very effective.', '2003-11-10 03:15:30.000000', NULL, 1),
(478529, 45391, 10170, '<td valign="top">Really lovely photo, the lighting makes it.  What surprises me is the unusual frame, those open ended black strips are excellent and really add to the photo.  I would never have thought of leaving the ends open, as it were, on this shot, but it is precisely the right thing to do.  Absolutely has to be in the running for a ribbon (I hope).</td>', 'Really lovely photo, the lighting makes it.  What surprises me is the unusual frame, those open ended black strips are excellent and really add to the photo.  I would never have thought of leaving the ends open, as it were, on this shot, but it is precisely the right thing to do.  Absolutely has to be in the running for a ribbon (I hope).', '2003-11-10 03:17:13.000000', NULL, 1),
(478530, 46252, 10170, '<td valign="top">That key makes all the difference.  Nice shot.</td>', 'That key makes all the difference.  Nice shot.', '2003-11-10 03:17:39.000000', NULL, 1),
(478531, 46014, 10170, '<td valign="top">Love the photo but don''t get the title (not that it matters to the score).</td>', 'Love the photo but don''t get the title (not that it matters to the score).', '2003-11-10 03:19:16.000000', NULL, 1),
(478533, 46319, 10170, '<td valign="top">How very very sad :(  Have never seen one of these.  Nicely taken photo, I like the way the point of interest is over to one side.</td>', 'How very very sad :(  Have never seen one of these.  Nicely taken photo, I like the way the point of interest is over to one side.', '2003-11-10 03:21:58.000000', NULL, 1),
(478534, 46336, 10170, '<td valign="top">Excellent shot.  This really works for me, can''t offer anything to improve it though, sorry.</td>', 'Excellent shot.  This really works for me, can''t offer anything to improve it though, sorry.', '2003-11-10 03:22:58.000000', NULL, 1),
(478536, 46221, 10170, '<td valign="top">Spectacular.  I love the clarity at the foreground compared to the misty background.  Great work.</td>', 'Spectacular.  I love the clarity at the foreground compared to the misty background.  Great work.', '2003-11-10 03:25:03.000000', NULL, 1),
(478538, 46215, 10170, '<td valign="top">Very effective indeed.</td>', 'Very effective indeed.', '2003-11-10 03:27:26.000000', NULL, 1),
