(478958, 46219, 10151, '<td valign="top">Seems a bit over-exposed, great composition!</td>', 'Seems a bit over-exposed, great composition!', '2003-11-10 13:30:53.000000', NULL, 1),
(478961, 46199, 11155, '<td valign="top">There seems to be a bit of noise/pixelation in the image.  Nice image, just not very captivating. Would have liked to have seen a different angle or point of view or non traditional lighting, maybe.</td>', 'There seems to be a bit of noise/pixelation in the image.  Nice image, just not very captivating. Would have liked to have seen a different angle or point of view or non traditional lighting, maybe.', '2003-11-10 13:32:35.000000', NULL, 1),
(478962, 46285, 11155, '<td valign="top">OK, that''s just funny.  Original.</td>', 'OK, that''s just funny.  Original.', '2003-11-10 13:33:14.000000', NULL, 1),
(478964, 46146, 11155, '<td valign="top">I like the point of view.</td>', 'I like the point of view.', '2003-11-10 13:33:51.000000', NULL, 1),
(478966, 46191, 11155, '<td valign="top">Great colors and lighting.</td>', 'Great colors and lighting.', '2003-11-10 13:36:21.000000', NULL, 1),
