(478978, 46230, 10691, '<td valign="top">Excellent use of both color and composure!</td>', 'Excellent use of both color and composure!', '2003-11-10 13:59:47.000000', NULL, 1),
(478979, 45391, 10691, '<td valign="top">I would not normally have thought a bath tub to be a sacred place. But your photograph speaks for itself -- profound!</td>', 'I would not normally have thought a bath tub to be a sacred place. But your photograph speaks for itself -- profound!', '2003-11-10 14:00:44.000000', NULL, 1),
(478981, 46221, 10691, '<td valign="top">Wonderful composure.</td>', 'Wonderful composure.', '2003-11-10 14:01:54.000000', NULL, 1),
