(479025, 46187, 6130, '<td valign="top">I like this very much.</td>', 'I like this very much.', '2003-11-10 14:38:04.000000', NULL, 1),
(479026, 46090, 12045, '<td valign="top">Great use of B&amp;W.</td>', 'Great use of B&W.', '2003-11-10 14:38:28.000000', NULL, 1),
