(479593, 45700, 12045, '<td valign="top">Great sky shot very nicely done.</td>', 'Great sky shot very nicely done.', '2003-11-10 21:24:57.000000', NULL, 1),
(479594, 46343, 7628, '<td valign="top">Nice saturated colors, I like the soft focus - can see enough to get a sense of what is in the background without it being too distracting.  The odd angle is almost as if one is reclining in the tub.   very nice. 9</td>', 'Nice saturated colors, I like the soft focus - can see enough to get a sense of what is in the background without it being too distracting.  The odd angle is almost as if one is reclining in the tub.   very nice. 9', '2003-11-10 21:26:26.000000', NULL, 1),
