(479597, 46000, 7628, '<td valign="top">nicely framed with the words behind.  Not very subtle, but effective.</td>', 'nicely framed with the words behind.  Not very subtle, but effective.', '2003-11-10 21:29:01.000000', NULL, 1),
(479599, 46238, 12611, '<td valign="top">Nice little birdhouse shot.I like the hardwood floor touch- but the light source should be deflected a bit- the reflection/glare off the top of the "steeple" is a bit much</td>', 'Nice little birdhouse shot.I like the hardwood floor touch- but the light source should be deflected a bit- the reflection/glare off the top of the "steeple" is a bit much', '2003-11-10 21:29:46.000000', NULL, 1),
(479600, 46017, 7628, '<td valign="top">The red and the stone are quite a combination!  So grand, and yet i the end your eye comes to that simple calm angel.  Wish the red paint weren''t quite so shiny. 8</td>', 'The red and the stone are quite a combination!  So grand, and yet i the end your eye comes to that simple calm angel.  Wish the red paint weren''t quite so shiny. 8', '2003-11-10 21:30:13.000000', NULL, 1),
(479601, 45875, 12045, '<td valign="top">That is one nice morning spot!  I''m jealous!  Great picture anyway.  The reflections in the lake are fantastic.</td>', 'That is one nice morning spot!  I''m jealous!  Great picture anyway.  The reflections in the lake are fantastic.', '2003-11-10 21:30:13.000000', NULL, 1),
(479603, 46287, 12611, '<td valign="top">Interesting subject but the shot seems a bit overexposed, might want to wait till the sun isn''t directly beyond the subjects in the composition. also, th ebright sun washed out the colors- I would like to see this shot in the dawn or dusk.</td>', 'Interesting subject but the shot seems a bit overexposed, might want to wait till the sun isn''t directly beyond the subjects in the composition. also, th ebright sun washed out the colors- I would like to see this shot in the dawn or dusk.', '2003-11-10 21:31:39.000000', NULL, 1),
