(485264, 46316, 6624, '<td valign="top">this is a very inviting and satisfying image, it invites one to the sacred/inner life</td>', 'this is a very inviting and satisfying image, it invites one to the sacred/inner life', '2003-11-14 11:11:54.000000', NULL, 1),
(485266, 45700, 6624, '<td valign="top">this is an amazing shot...there at the right time and place I guess</td>', 'this is an amazing shot...there at the right time and place I guess', '2003-11-14 11:12:38.000000', NULL, 1),
