INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(487440, 46250, 11855, '<td valign="top">nice work..... another top 20-sweet</td>', 'nice work..... another top 20-sweet', '2003-11-17 00:06:17.000000', NULL, 0),
(487443, 45700, 1280, '<td valign="top">Well I think one of the things I''ve learned about sunsets, is to use my exposure compensation.  I like to under-expose to deepen the colours and avoid wash-out.  It works for me, and I take pics of the sunset almost every night.<br/>Thanks for the votes and comments folks.</td>', 'Well I think one of the things I''ve learned about sunsets, is to use my exposure compensation.  I like to under-expose to deepen the colours and avoid wash-out.  It works for me, and I take pics of the sunset almost every night.Thanks for the votes and comments folks.', '2003-11-17 00:07:57.000000', NULL, 0),
(487452, 46219, 11855, '<td valign="top">thank you for your comments...... I had this shot. just didn''t get the exposure correct.....had no idea what the best way to shoot the inside of the church and retain the lighting... A longer eposure at f22 would have be the way to go..</td>', 'thank you for your comments...... I had this shot. just didn''t get the exposure correct.....had no idea what the best way to shoot the inside of the church and retain the lighting... A longer eposure at f22 would have be the way to go..', '2003-11-17 00:12:01.000000', NULL, 0),
(487463, 45665, 6458, '<td valign="top">I thought I recognized the deft touch of JJ in this shot! It''s great picture too, one of my highest rated this week and a deserved ribbon.</td>', 'I thought I recognized the deft touch of JJ in this shot! It''s great picture too, one of my highest rated this week and a deserved ribbon.', '2003-11-17 00:20:59.000000', NULL, 0),
(487469, 45700, 714, '<td valign="top"><b>Wow!</b>  Gracious, this is a beautiful shot.  Congrats on your first ribbon.  You deserve it.  I bet you are jazzed.  This is one of my favorites.  God bless you, sister!<br/> <br/>Oops, I mean second ribbon. :-)<br/><br/><i>Message edited by author 2003-11-17 18:49:14.</i></td>', 'Wow!  Gracious, this is a beautiful shot.  Congrats on your first ribbon.  You deserve it.  I bet you are jazzed.  This is one of my favorites.  God bless you, sister! Oops, I mean second ribbon. :-)', '2003-11-17 00:25:11.000000', '2003-11-17 18:49:14.000000', 0),
(487472, 45939, 714, '<td valign="top">Woohooo! Very nice. Congrats, M!</td>', 'Woohooo! Very nice. Congrats, M!', '2003-11-17 00:26:39.000000', NULL, 0),
(487473, 45700, 6458, '<td valign="top">Wonderful sunset shot, I like that there is no landscape present. It serves to highlight all the wonderful cloud formations.. Good job and congrats on the ribbon!</td>', 'Wonderful sunset shot, I like that there is no landscape present. It serves to highlight all the wonderful cloud formations.. Good job and congrats on the ribbon!', '2003-11-17 00:26:47.000000', NULL, 0),
(487474, 45665, 714, '<td valign="top">JJ, you''ve won again.  Way to go! Congrats.</td>', 'JJ, you''ve won again.  Way to go! Congrats.', '2003-11-17 00:27:33.000000', NULL, 0),
(487476, 46265, 11078, '<td valign="top">I am amazed this one didnt do better I thought it was a lovely photo!</td>', 'I am amazed this one didnt do better I thought it was a lovely photo!', '2003-11-17 00:31:05.000000', NULL, 0),
(487479, 46221, 8953, '<td valign="top">A long way from where you started! Good job, and welcome to the top TEN!<br/> <br/>Richard</td>', 'A long way from where you started! Good job, and welcome to the top TEN! Richard', '2003-11-17 00:33:07.000000', NULL, 0),
(487483, 46014, 7151, '<td valign="top">Bummer.  I wrote about a 100 word critique on this one, but somewhere the critique and my vote were lost.  :(  To sum up, I loved the image, the lines, the tones and the contrasts.  I would have liked the tree not cut off, but it wasn''t a big deal.  I spent nearly an hour trying to figure out the title (based at least somewhat on your "interchange" in the rant forum), and honestly didn''t find anything related to the description you gave.  But I did find several wicca, wizardry and new-age references to 13-moon cycles/systems, though nothing that seemed to relate to the image.  I tried to give you a 6 - but it didn''t take.  Nice piece of work.</td>', 'Bummer.  I wrote about a 100 word critique on this one, but somewhere the critique and my vote were lost.  :(  To sum up, I loved the image, the lines, the tones and the contrasts.  I would have liked the tree not cut off, but it wasn''t a big deal.  I spent nearly an hour trying to figure out the title (based at least somewhat on your "interchange" in the rant forum), and honestly didn''t find anything related to the description you gave.  But I did find several wicca, wizardry and new-age references to 13-moon cycles/systems, though nothing that seemed to relate to the image.  I tried to give you a 6 - but it didn''t take.  Nice piece of work.', '2003-11-17 00:35:57.000000', NULL, 0),
(487485, 45939, 8953, '<td valign="top">Congrats! You done good!<br/> <br/>Richard</td>', 'Congrats! You done good! Richard', '2003-11-17 00:36:12.000000', NULL, 0),
(487490, 45700, 8953, '<td valign="top">I had said your tenth WOW was from me:) I was only off by one LOL! wonderful job! With My favorites now. <br/> <br/>Congrats on the ribbon<br/> <br/>Richard</td>', 'I had said your tenth WOW was from me:) I was only off by one LOL! wonderful job! With My favorites now.  Congrats on the ribbon Richard', '2003-11-17 00:40:00.000000', NULL, 0),
(487493, 45700, 5313, '<td valign="top">Oh, Grayce, congrats!  This was one of my very top photos in this challenge.  I sat and looked at it for a long time--many times!  I''d love a place like that to talk to God.</td>', 'Oh, Grayce, congrats!  This was one of my very top photos in this challenge.  I sat and looked at it for a long time--many times!  I''d love a place like that to talk to God.', '2003-11-17 00:41:08.000000', NULL, 0),
(487500, 45665, 8953, '<td valign="top">Another Ribbon! how am I ever going to catch up JJ!!??  A wonderful talent you have.<br/> <br/>Richard</td>', 'Another Ribbon! how am I ever going to catch up JJ!!??  A wonderful talent you have. Richard', '2003-11-17 00:46:08.000000', NULL, 0),
(487515, 45665, 6388, '<td valign="top">JJ - I love you, man.  Another brilliant effort.<br/> <br/>Pedro</td>', 'JJ - I love you, man.  Another brilliant effort. Pedro', '2003-11-17 01:12:01.000000', NULL, 0),
(487518, 46114, 7969, '<td valign="top">Shot suggestions/critique: <br/>I would consider reshooting it at dusk, dawn or other light that is not so harsh (i.e. midday).  <br/>The shot while being in focus and sharp lacks ''wow'' to me.   Perhaps more ''umph''  if the bell was moving.  Adjusting  the composition some may also help as is it is  dead on straightforward.  I am not sure if it is because of the curve in the building but the top of the shot looks slanted a bit to the right which I find distracting. <br/>The subject while fitting the challenge is a likely subject, which IMO means the way it is shot should be ''extra-ordinary'', creative or sensitve to the light conditions on subject.  <br/>This is my first CC attempt I hope it helps, they are just my ideas  you have been at this longer than I : ). <br/>I tried to look at it as critically as possible because it is what I would like from a critique.  Was hard shot to give feedback on because no huge obvious flaws.  <br/>Happy shooting, if you do reshoot this one, would like to see it and I really like your title choice.<br/></td>', 'Shot suggestions/critique: I would consider reshooting it at dusk, dawn or other light that is not so harsh (i.e. midday).  The shot while being in focus and sharp lacks ''wow'' to me.   Perhaps more ''umph''  if the bell was moving.  Adjusting  the composition some may also help as is it is  dead on straightforward.  I am not sure if it is because of the curve in the building but the top of the shot looks slanted a bit to the right which I find distracting. The subject while fitting the challenge is a likely subject, which IMO means the way it is shot should be ''extra-ordinary'', creative or sensitve to the light conditions on subject.  This is my first CC attempt I hope it helps, they are just my ideas  you have been at this longer than I : ). I tried to look at it as critically as possible because it is what I would like from a critique.  Was hard shot to give feedback on because no huge obvious flaws.  Happy shooting, if you do reshoot this one, would like to see it and I really like your title choice.', '2003-11-17 01:13:48.000000', NULL, 0),
(487531, 46014, 1031, '<td valign="top">I kind-of figured out that it was a long shot of a city from some shoreline, but didn''t recognized the specific location. Must be because the couple of times I''ve been at Jericho Beach (staying at the youth hostel there) I never got down low for that kind of view.<br/> <br/>I''ve wanted to take a shot across the beach with the ski run in the background -- I think it''s just to the left of your shot here.<br/> <br/>Thanks for the background info -- I think finding out all this "regional" knowledge is one of the most interesting things about participating here.</td>', 'I kind-of figured out that it was a long shot of a city from some shoreline, but didn''t recognized the specific location. Must be because the couple of times I''ve been at Jericho Beach (staying at the youth hostel there) I never got down low for that kind of view. I''ve wanted to take a shot across the beach with the ski run in the background -- I think it''s just to the left of your shot here. Thanks for the background info -- I think finding out all this "regional" knowledge is one of the most interesting things about participating here.', '2003-11-17 01:26:51.000000', NULL, 0),
(487532, 46288, 12661, '<td valign="top">I couldn''t disagree more with the scores you got on this photo. Maybe there just aren''t enough fishermen in our ranks who can appreciate the sacrednous of a trout hole. When I saw the photo I could just picture the trout lurking in the eddy just waiting for a fly to float down through the current. Nicely done.</td>', 'I couldn''t disagree more with the scores you got on this photo. Maybe there just aren''t enough fishermen in our ranks who can appreciate the sacrednous of a trout hole. When I saw the photo I could just picture the trout lurking in the eddy just waiting for a fly to float down through the current. Nicely done.', '2003-11-17 01:32:41.000000', NULL, 0),
(487586, 46078, 8682, '<td valign="top">Thanks for all your votes and comments! I´m really glad with this place and average. It´s my best shot... Thanks</td>', 'Thanks for all your votes and comments! I´m really glad with this place and average. It´s my best shot... Thanks', '2003-11-17 02:07:33.000000', NULL, 0),
(487609, 45939, 12802, '<td valign="top">Well done, knew this would do it!</td>', 'Well done, knew this would do it!', '2003-11-17 02:34:51.000000', NULL, 0),
(487610, 45700, 12802, '<td valign="top">Well done, congratulations on the 2nd place!</td>', 'Well done, congratulations on the 2nd place!', '2003-11-17 02:36:11.000000', NULL, 0),
(487611, 45665, 12802, '<td valign="top">Brilliant! Well done.</td>', 'Brilliant! Well done.', '2003-11-17 02:37:43.000000', NULL, 0),
(487660, 45939, 6458, '<td valign="top">Thanks guys for the comments and the votes. This has been a shot I''ve been wanting to take since I first saw the church lit up. When I saw the sacred places challenge, I figured "What the hey.. might as well go take a picture of it now." This particular shot was from the first evening I tried, and to be honest, I was hoping to get it a bit lighter in the sky. <br/> <br/>I went back the next evening to attempt to do that and captured this:<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=45931" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/6458/thumb/45931.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/6458/thumb/45931.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/6458/thumb/45931.jpg"/></a> <br/> <br/>I think the first is the stronger of the two, but the exposure on the tower is better on the second.</td>', 'Thanks guys for the comments and the votes. This has been a shot I''ve been wanting to take since I first saw the church lit up. When I saw the sacred places challenge, I figured "What the hey.. might as well go take a picture of it now." This particular shot was from the first evening I tried, and to be honest, I was hoping to get it a bit lighter in the sky.  I went back the next evening to attempt to do that and captured this:  I think the first is the stronger of the two, but the exposure on the tower is better on the second.', '2003-11-17 04:06:23.000000', NULL, 0),
(487669, 46164, 13440, '<td valign="top">Thanks every comments on my first submission!!</td>', 'Thanks every comments on my first submission!!', '2003-11-17 04:27:56.000000', NULL, 0),
(487670, 45939, 6999, '<td valign="top">Congratulations Matt - had to get a blue onto your profile sooner or later. Great work.</td>', 'Congratulations Matt - had to get a blue onto your profile sooner or later. Great work.', '2003-11-17 04:27:59.000000', NULL, 0),
(487685, 45700, 3585, '<td valign="top">All three winning entries clearly illustrate the fact that the "time factor" in rendering a atmosphere of sacredness or at least a glimpse of bliss through photography is as important as the location itself. What metaphysical strength would these three images have if they had been shot at high noon?  <br/>On this occasion you clarly were blessed with a perfect sense of timing.<br/>congratulations.</td>', 'All three winning entries clearly illustrate the fact that the "time factor" in rendering a atmosphere of sacredness or at least a glimpse of bliss through photography is as important as the location itself. What metaphysical strength would these three images have if they had been shot at high noon?  On this occasion you clarly were blessed with a perfect sense of timing.congratulations.', '2003-11-17 04:57:19.000000', NULL, 0),
(487686, 45939, 3585, '<td valign="top">Great timing! this shot would be practically be impossible to succeed at with no natural light at all. congrats for the blue!</td>', 'Great timing! this shot would be practically be impossible to succeed at with no natural light at all. congrats for the blue!', '2003-11-17 05:03:03.000000', NULL, 0),
(487688, 45939, 2716, '<td valign="top">Matt! 3 words: You Da Man !!!  The lighting on this photo is awesome. You deserved the blue ribbon.</td>', 'Matt! 3 words: You Da Man !!!  The lighting on this photo is awesome. You deserved the blue ribbon.', '2003-11-17 05:51:03.000000', NULL, 0),
(487732, 46278, 2634, '<td valign="top">For those of you that commented about the lights- there was a spotlight lighting the church. It was off to the left(obviously). Yes it was too harsh, but I couldn''t do anything about it.  I adjusted the curves and levels, and even changed the white and neutrals selectively, but I guess it wasn''t enough.<br/>Next time there is a challenge I don''t like, I will sit it out. :)</td>', 'For those of you that commented about the lights- there was a spotlight lighting the church. It was off to the left(obviously). Yes it was too harsh, but I couldn''t do anything about it.  I adjusted the curves and levels, and even changed the white and neutrals selectively, but I guess it wasn''t enough.Next time there is a challenge I don''t like, I will sit it out. :)', '2003-11-17 07:36:34.000000', NULL, 0),
(487734, 45700, 6624, '<td valign="top">Congratulations - this was one of my favorites in the challenge and now will really go to favorites.  Anne</td>', 'Congratulations - this was one of my favorites in the challenge and now will really go to favorites.  Anne', '2003-11-17 07:39:36.000000', NULL, 0),
(487736, 45939, 6624, '<td valign="top">Congratulations on the blue...well deserved.  Anne</td>', 'Congratulations on the blue...well deserved.  Anne', '2003-11-17 07:41:11.000000', NULL, 0),
(487737, 45665, 6624, '<td valign="top">Congratulations on the placement, it''s a stunning shot.  Anne</td>', 'Congratulations on the placement, it''s a stunning shot.  Anne', '2003-11-17 07:42:24.000000', NULL, 0),
(487739, 46221, 6624, '<td valign="top">Thank you to every single one of you...Firstrich1 made me laugh with that comment.  I couldn''t even get the size right in my first entry. This is pretty overwhelming.  Anne</td>', 'Thank you to every single one of you...Firstrich1 made me laugh with that comment.  I couldn''t even get the size right in my first entry. This is pretty overwhelming.  Anne', '2003-11-17 07:44:40.000000', NULL, 0),
(487744, 46291, 6624, '<td valign="top">Congratulations on the top 10 placement, a lovely shot.</td>', 'Congratulations on the top 10 placement, a lovely shot.', '2003-11-17 07:52:56.000000', NULL, 0),
(487745, 46078, 6624, '<td valign="top">Congratulations on a nice finish, really lovely.</td>', 'Congratulations on a nice finish, really lovely.', '2003-11-17 07:53:59.000000', NULL, 0),
(487746, 46184, 6624, '<td valign="top">Congratulatons on this.  I didn''t recognize it although I was there for the Olympics.  I like the 180 degree turn, your wife must be very wise (lol)</td>', 'Congratulatons on this.  I didn''t recognize it although I was there for the Olympics.  I like the 180 degree turn, your wife must be very wise (lol)', '2003-11-17 07:56:07.000000', NULL, 0),
(487749, 45268, 6624, '<td valign="top">Very nice image and congratulkations on the top ten placement.  Anne</td>', 'Very nice image and congratulkations on the top ten placement.  Anne', '2003-11-17 07:56:50.000000', NULL, 0),
(487751, 46334, 7485, '<td valign="top">I guess my mistake was to not include the word "moon" in the title. I still can''t believe that some people thought I just hadn''t bothered to crop out some random light in the corner. If I were that lousy a photographer, I wouldn''t be entering in DPC!<br/> <br/>But thanks to the rest of you for your constructive comments!<br/> <br/></td>', 'I guess my mistake was to not include the word "moon" in the title. I still can''t believe that some people thought I just hadn''t bothered to crop out some random light in the corner. If I were that lousy a photographer, I wouldn''t be entering in DPC! But thanks to the rest of you for your constructive comments! ', '2003-11-17 08:00:17.000000', NULL, 0),
(487757, 45939, 6870, '<td valign="top">Congratulations Matt on a well deserved ribbon!</td>', 'Congratulations Matt on a well deserved ribbon!', '2003-11-17 08:07:21.000000', NULL, 0),
